<?php declare(strict_types=1);$this->layout('layouts/default',['title'=>$title,'currentPage'=>null]);?>
<section class="studio-page"><header class="studio-page-heading"><div><p class="studio-eyebrow">STUDIO</p><h2>Busca global</h2><p>Conteúdo, usuários e propostas em uma única consulta.</p></div><span class="studio-badge"><?= count($results) ?> resultado(s)</span></header><form class="studio-form-card studio-search-page" method="get"><label><span>Buscar no Studio</span><input type="search" name="q" value="<?= $this->e($query) ?>" minlength="2" maxlength="100" required autofocus></label><button>Buscar</button></form><?php if($query!==''&&mb_strlen($query)<2):?><p class="studio-panel studio-empty">Digite ao menos dois caracteres.</p><?php elseif($query!==''&&$results===[]):?><p class="studio-panel studio-empty">Nenhum resultado encontrado.</p><?php else:?><div class="studio-search-results"><?php foreach($results as $result):?><a class="studio-panel" href="<?= $this->e($result['url']) ?>"><small><?= $this->e($result['group']) ?></small><strong><?= $this->e($result['label']) ?></strong><span><?= $this->e($result['detail']) ?></span></a><?php endforeach;?></div><?php endif;?></section>
